import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;

/** Pure N03/N06 execution authority. A real deterministic computation and registered immutable
 * objects replace, not imitate, a professional process, provider call, or usage receipt. */
public final class FormalEvaluationDeterministicRuntime {
 private final FormalCapabilityIdentityAuthority capabilities;private final JdbcTemplate db;private final PermissionSchema json;private final FormalEvaluationJobs jobs;private final FormalEvaluationLaunchLedger launches;private final FormalEvaluationNodeLeases leases;private final FormalEvaluationNodeInputs inputs;private final FormalEvaluationDeterministicObjects objects;
 private final JsonMapper parser=JsonMapper.builder().propertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE).enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
 public FormalEvaluationDeterministicRuntime(DataSource data,PermissionSchema json,FormalEvaluationJobs jobs,FormalEvaluationLaunchLedger launches,FormalEvaluationNodeLeases leases,FormalEvaluationNodeInputs inputs,FormalEvaluationDeterministicObjects objects,FormalCapabilityIdentityAuthority capabilities){this.capabilities=capabilities;db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.jobs=jobs;this.launches=launches;this.leases=leases;this.inputs=inputs;this.objects=objects;}
 public Prepared prepare(EnterpriseAccess.Admission a,FormalEvaluationProtocol.Reference ref,FormalEvaluationProtocol.Step step,FormalEvaluationNodeInputs.Verified input,String service)throws Exception {
  requireNode(input.node().node());var job=jobs.byRun(a,ref.runId());launches.requireAccepted(a,job,ref);input.requireCurrent(a);
  var old=executions(job.tenantId(),job.runId(),step.stepId());if(!old.isEmpty())return restore(a,ref,step,input);
  var lease=leases.acquire(a,job,ref,step,input,service);lease.requireDispatchCurrent();String execution=id(),audit=id(),event=id();
  var envelope=base(step.nodeKind(),job.runId(),step.stepId(),execution,lease.actionId(),input.sha256());envelope.set("compiler",input.evidence());
  var declared=outputDeclaration(a,job.projectId(),input.node().node());
  var result=new FormalEvaluationBusinessChecks(json).checkDeterministic(step.nodeKind(),execution,lease.actionId(),input.evidence(),declared.required("schema_ref").asText(),declared.required("schema_sha256").asText());
  var evidence=json.object();evidence.set("envelope",envelope);evidence.set("output",result.output());evidence.put("state",result.state());String canonical=json.canonical(evidence);var now=now();
  journal(job,audit,event,"evaluation.deterministic.executed",execution,evidence,now);
  changed(db.update("INSERT INTO formal_evaluation_deterministic_execution (tenant_id,project_id,run_id,step_id,execution_id,action_id,lease_generation,input_artifact_id,input_sha256,canonical_execution,execution_sha256,audit_id,event_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES (?,?,?,?,?,?,1,?,?,?,?,?,?,'1.0.0',?,?,?,?)",job.tenantId(),job.projectId(),job.runId(),step.stepId(),execution,lease.actionId(),input.artifact().artifactId(),input.sha256(),canonical,hash(evidence),audit,event,json.manifestSha256(),job.actorId(),now,job.classification()));
  return restore(a,ref,step,input);
 }
 public Prepared restore(EnterpriseAccess.Admission a,FormalEvaluationProtocol.Reference ref,FormalEvaluationProtocol.Step step,FormalEvaluationNodeInputs.Verified input)throws Exception {
  var job=jobs.byRun(a,ref.runId());launches.requireAccepted(a,job,ref);requireNode(input.node().node());if(!ref.steps().contains(step)||!step.stepId().equals(input.node().stepId())||!step.nodeSha256().equals(input.node().nodeSha256()))bad();
  var proof=new Prepared(ref,step,input,job,one(executions(job.tenantId(),job.runId(),step.stepId())));proof.requireCurrent(a);return proof;
 }
 public final class Prepared {
  private final FormalEvaluationProtocol.Reference reference;private final FormalEvaluationProtocol.Step step;private final FormalEvaluationNodeInputs.Verified input;private final FormalEvaluationJobs.Job job;private final Map<String,Object> row;private final JsonNode evidence;
  private Prepared(FormalEvaluationProtocol.Reference ref,FormalEvaluationProtocol.Step step,FormalEvaluationNodeInputs.Verified input,FormalEvaluationJobs.Job job,Map<String,Object> row)throws Exception{reference=ref;this.step=step;this.input=input;this.job=job;this.row=Map.copyOf(row);evidence=parser.readTree(text(row,"canonical_execution"));}
  public void requireCurrent(EnterpriseAccess.Admission a)throws Exception {
   FormalEvaluationExecutionAdmission.current(a);input.requireCurrent(a);same(job,jobs.byRun(a,job.runId()));launches.requireAccepted(a,job,reference);same(row,one(executions(job.tenantId(),job.runId(),step.stepId())));
   if(!db.queryForList("SELECT receipt_id FROM formal_evaluation_cancel_intent WHERE tenant_id=? AND run_id=? LIMIT 1",job.tenantId(),job.runId()).isEmpty())throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
   same("RUNNING",one(db.query("SELECT status FROM system_job_run WHERE tenant_id=? AND run_id=? AND ended_at IS NULL LIMIT 2",(r,n)->r.getString(1),job.tenantId(),job.runId())));
   verifyExecution(a,job,input.node(),row,input.artifact(),input.evidence());
  }
  public FormalEvaluationJobs.Job job(){input.reads().requireActive();return job;}public FormalEvaluationJobs.NodeRow node(){return input.node();}
  public JsonNode evidence(){input.reads().requireActive();return evidence.deepCopy();}
  public List<PermissionProtocol.Basis> roots(){return List.of(new PermissionProtocol.Basis(input.artifact().artifactId(),input.artifact().sha256()));}
  public byte[] bytes(String kind)throws Exception {
   JsonNode value=switch(kind){case "STEP_ENVELOPE"->evidence.required("envelope");case "BUSINESS_OUTPUT"->evidence.required("output");case "STEP_RESULT"->{var result=(ObjectNode)evidence.required("envelope").deepCopy();result.remove("compiler");result.put("state",text(evidence,"state")).put("output_sha256",hash(evidence.required("output")));yield result;}default->throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);};
   return json.canonical(value).getBytes(StandardCharsets.UTF_8);
  }
 }
 public FormalEvaluationProtocol.NodeReceipt finish(EnterpriseAccess.Admission a,Prepared proof,FormalEvaluationDeterministicObjects.Registered envelope,FormalEvaluationDeterministicObjects.Registered output,FormalEvaluationDeterministicObjects.Registered result)throws Exception {
  proof.requireCurrent(a);for(var object:List.of(envelope,output,result))object.requireUnchanged();var j=proof.job();String step=proof.node().stepId();
  for(var entry:Map.of("STEP_ENVELOPE",envelope,"BUSINESS_OUTPUT",output,"STEP_RESULT",result).entrySet()){var original=objects.readOriginal(a,j.runId(),step,entry.getKey());same(entry.getValue().artifact(),original.artifact());same(new String(proof.bytes(entry.getKey()),StandardCharsets.UTF_8),original.payload());same(proof.evidence(),original.evidence());}
  var old=outcomes(j.tenantId(),j.runId(),step);if(!old.isEmpty())return originalReceipt(a,j.runId(),step);
  String id=id(),audit=id(),event=id(),state=text(proof.evidence,"state");var evidence=json.object().put("schema_version","1.0.0").put("receipt_id",id).put("run_id",j.runId()).put("step_id",step).put("node_sha256",proof.node().nodeSha256()).put("state",state).put("deterministic_execution_id",text(proof.row,"execution_id")).put("execution_sha256",text(proof.row,"execution_sha256"));
  evidence.set("input",json.tree(proof.input.artifact()));evidence.set("step_envelope",json.tree(envelope.artifact()));evidence.set("business_output",json.tree(output.artifact()));evidence.set("step_result",json.tree(result.artifact()));String digest=hash(evidence);
  var record=new FormalEvaluationExecutionProtocol.Record(proof.node().node(),j.runId(),step,1,proof.input.artifact(),envelope.artifact(),result.artifact(),null,List.of(),List.of(output.artifact()),List.of(),launches.requireOriginalAccepted(a,j),digest);var at=now();journal(j,audit,event,"evaluation.deterministic.completed",id,evidence,at);
  changed(db.update("INSERT INTO formal_evaluation_deterministic_outcome (tenant_id,project_id,run_id,step_id,lease_generation,receipt_id,state,canonical_receipt,receipt_sha256,canonical_record,record_sha256,audit_id,event_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES (?,?,?,?,1,?,?,?,?,?,?,?,?,'1.0.0',?,?,?,?)",j.tenantId(),j.projectId(),j.runId(),step,id,state,json.canonical(evidence),digest,json.canonical(json.tree(record)),hash(json.tree(record)),audit,event,json.manifestSha256(),j.actorId(),at,j.classification()));
  changed(db.update("UPDATE run_step SET status=?,output_ref=?,revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE tenant_id=? AND run_id=? AND step_id=? AND status='RUNNING' AND lease_generation=1",state,json.canonical(json.tree(output.artifact())),j.tenantId(),j.runId(),step));return originalReceipt(a,j.runId(),step);
 }
 public FormalEvaluationProtocol.NodeReceipt originalReceipt(EnterpriseAccess.Admission a,String run,String step)throws Exception {var original=original(a,run,step);return new FormalEvaluationProtocol.NodeReceipt("1.0.0",run,step,original.node.nodeSha256(),text(original.row,"state"),text(original.row,"receipt_id"),text(original.row,"receipt_sha256"));}
 private record Original(FormalEvaluationJobs.Job job,FormalEvaluationJobs.NodeRow node,Map<String,Object> row,FormalEvaluationExecutionProtocol.Record record,PermissionProtocol.Basis output){}
 private Original original(EnterpriseAccess.Admission a,String run,String step)throws Exception {
  FormalEvaluationExecutionAdmission.current(a);var job=jobs.original(a,run);var node=one(job.nodes().stream().filter(n->n.stepId().equals(step)).toList());requireNode(node.node());var row=one(outcomes(job.tenantId(),run,step));metadata(job,row);
  var evidence=parser.readTree(text(row,"canonical_receipt"));same(hash(evidence),row.get("receipt_sha256"));same(json.canonical(evidence),row.get("canonical_receipt"));for(String key:List.of("run_id","step_id","receipt_id","state"))same(text(row,key),text(evidence,key));same(node.nodeSha256(),text(evidence,"node_sha256"));
  journalOriginal(job,row,"evaluation.deterministic.completed",text(row,"receipt_id"),evidence);
  var record=parser.readValue(text(row,"canonical_record"),FormalEvaluationExecutionProtocol.Record.class);same(hash(json.tree(record)),row.get("record_sha256"));same(json.canonical(json.tree(record)),row.get("canonical_record"));same(node.node(),record.node());same(run,record.runId());same(step,record.stepId());same(1L,record.leaseGeneration());same(1L,((Number)row.get("lease_generation")).longValue());same(text(row,"receipt_sha256"),record.stepReceiptSha256());same(launches.requireOriginalAccepted(a,job),record.runReceiptSha256());if(record.sessionExport()!=null||!record.invocations().isEmpty()||!record.checkIds().isEmpty())bad();
  var envelope=objects.readOriginal(a,run,step,"STEP_ENVELOPE");var output=objects.readOriginal(a,run,step,"BUSINESS_OUTPUT");var result=objects.readOriginal(a,run,step,"STEP_RESULT");same(record.stepEnvelope(),envelope.artifact());same(record.stepResult(),result.artifact());same(List.of(output.artifact()),record.actualArtifacts());
  for(var entry:Map.of("input",record.inputManifest(),"step_envelope",envelope.artifact(),"business_output",output.artifact(),"step_result",result.artifact()).entrySet())same(json.tree(entry.getValue()),evidence.required(entry.getKey()));
  var compiled=parser.readTree(envelope.payload());var execution=one(executions(job.tenantId(),run,step));same(text(execution,"execution_id"),text(evidence,"deterministic_execution_id"));same(text(execution,"execution_sha256"),text(evidence,"execution_sha256"));verifyExecution(a,job,node,execution,record.inputManifest(),compiled.required("compiler"));
  var computation=parser.readTree(text(execution,"canonical_execution"));same(compiled,computation.required("envelope"));same(parser.readTree(output.payload()),computation.required("output"));same(text(row,"state"),text(computation,"state"));for(var object:List.of(envelope,output,result))same(computation,object.evidence());
  var terminal=(ObjectNode)compiled.deepCopy();terminal.remove("compiler");terminal.put("state",text(computation,"state")).put("output_sha256",hash(computation.required("output")));same(terminal,parser.readTree(result.payload()));
  var actual=one(db.queryForList("SELECT status,input_sha256,lease_generation,output_ref FROM run_step WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",job.tenantId(),run,step));same(row.get("state"),actual.get("status"));same(record.inputManifest().sha256(),actual.get("input_sha256"));same(1L,((Number)actual.get("lease_generation")).longValue());same(json.tree(output.artifact()),parser.readTree(text(actual,"output_ref")));
  return new Original(job,node,Map.copyOf(row),record,new PermissionProtocol.Basis(output.artifact().artifactId(),output.artifact().sha256()));
 }
 public Completed requireCompleted(EnterpriseAccess.Admission a,String run,String step)throws Exception {var original=original(a,run,step);same("SUCCEEDED",text(original.row,"state"));return new Completed(a,original);}
 public final class Completed {
  private final EnterpriseAccess.Admission admission;private final Original original;
  private Completed(EnterpriseAccess.Admission a,Original original){admission=a;this.original=original;}
  public void requireCurrent()throws Exception{same(original,original(admission,original.record.runId(),original.record.stepId()));}
  public FormalEvaluationExecutionProtocol.Record record(){FormalEvaluationExecutionAdmission.current(admission);return original.record;}public PermissionProtocol.Basis output(){FormalEvaluationExecutionAdmission.current(admission);return original.output;}
  public String receiptId(){FormalEvaluationExecutionAdmission.current(admission);return text(original.row,"receipt_id");}public String receiptSha256(){FormalEvaluationExecutionAdmission.current(admission);return text(original.row,"receipt_sha256");}
 }
 private void verifyExecution(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job job,FormalEvaluationJobs.NodeRow node,Map<String,Object> row,FormalEvaluationExecutionProtocol.Artifact input,JsonNode compiler)throws Exception {
  metadata(job,row);same(job.runId(),text(row,"run_id"));same(node.stepId(),text(row,"step_id"));same(input.artifactId(),text(row,"input_artifact_id"));same(input.sha256(),text(row,"input_sha256"));same(1L,((Number)row.get("lease_generation")).longValue());requireNode(node.node());
  inputs.requireOriginal(a,job.runId(),new FormalEvaluationProtocol.Step(node.stepId(),node.node().nodeKind(),node.nodeSha256()),input,compiler);
  var evidence=parser.readTree(text(row,"canonical_execution"));same(json.canonical(evidence),row.get("canonical_execution"));same(hash(evidence),row.get("execution_sha256"));var envelope=base(node.node().nodeKind(),job.runId(),node.stepId(),text(row,"execution_id"),text(row,"action_id"),input.sha256());envelope.set("compiler",compiler);same(envelope,evidence.required("envelope"));
  var declared=outputDeclaration(a,job.projectId(),node.node());
  var result=new FormalEvaluationBusinessChecks(json).checkDeterministic(node.node().nodeKind(),text(row,"execution_id"),text(row,"action_id"),compiler,declared.required("schema_ref").asText(),declared.required("schema_sha256").asText());same(result.output(),evidence.required("output"));same(result.state(),text(evidence,"state"));
  var dispatch=one(db.queryForList("SELECT action_id,input_artifact_id,input_sha256,lease_generation FROM formal_evaluation_node_dispatch WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",job.tenantId(),job.runId(),node.stepId()));for(String key:List.of("action_id","input_artifact_id","input_sha256","lease_generation"))same(row.get(key),dispatch.get(key));
  if(!db.queryForList("SELECT invocation_id FROM invocation WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 1",job.tenantId(),job.runId(),node.stepId()).isEmpty()||!db.queryForList("SELECT session_id FROM professional_runtime_session WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 1",job.tenantId(),job.runId(),node.stepId()).isEmpty())bad();
  if(!db.queryForList("SELECT step_id FROM formal_evaluation_node_result WHERE tenant_id=? AND run_id=? AND step_id=? UNION ALL SELECT step_id FROM formal_evaluation_professional_completion WHERE tenant_id=? AND run_id=? AND step_id=?",job.tenantId(),job.runId(),node.stepId(),job.tenantId(),job.runId(),node.stepId()).isEmpty())bad();
  journalOriginal(job,row,"evaluation.deterministic.executed",text(row,"execution_id"),evidence);
 }
 private JsonNode outputDeclaration(EnterpriseAccess.Admission a,String project,FormalEvaluationExecutionProtocol.Node node)throws Exception {
  var role=capabilities.require(a,node.role(),"ROLE",project,"EVALUATION_RESULTS");var declared=role.canonicalDefinition().required("request").required("output_schema_ref");
  var selected=SchemaCatalogue.fromClasspath().requirePublished(declared.required("schema_ref").asText(),declared.required("schema_sha256").asText());
  if(!Set.of("artifacts","artifacts-v2").contains(selected.name())||!("N03".equals(node.nodeKind())?"FieldCheckResult":"AssemblyManifest").equals(selected.definition()))bad();role.requireUnchanged();return declared.deepCopy();
 }
 private ObjectNode base(String kind,String run,String step,String execution,String action,String input)throws Exception{return json.object().put("schema_version","1.0.0").put("execution_kind","SYSTEM_JOB").put("job_type","EVALUATION_VERIFICATION").put("node_kind",kind).put("execution_id",execution).put("run_id",run).put("step_id",step).put("action_id",action).put("input_sha256",input).put("implementation_sha256",implementationSha256());}
 private String implementationSha256()throws Exception{var parts=json.object();for(var type:List.of(FormalEvaluationDeterministicRuntime.class,FormalEvaluationBusinessChecks.class,TaskStrictFieldCheck.class,StrictFieldComparisonEngine.class,DocumentBodySemantics.class,RuleExpression.class)){try(var in=Objects.requireNonNull(type.getResourceAsStream("/"+type.getName().replace('.','/')+".class"))){parts.put(type.getName(),WireValues.sha256(in.readAllBytes()));}}return hash(parts);}
 private void metadata(FormalEvaluationJobs.Job j,Map<String,Object> row){for(var e:Map.of("tenant_id",j.tenantId(),"project_id",j.projectId(),"created_by",j.actorId(),"classification",j.classification(),"schema_version","1.0.0","schema_manifest_sha256",json.manifestSha256()).entrySet())same(e.getValue(),row.get(e.getKey()));}
 private void journal(FormalEvaluationJobs.Job j,String audit,String event,String action,String target,JsonNode evidence,java.sql.Timestamp at)throws Exception{String body=json.canonical(evidence);changed(db.update("INSERT INTO audit_event (tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES (?,?,?,?,?,?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",j.tenantId(),j.projectId(),audit,j.actorId(),action,body,target,j.runId(),json.manifestSha256(),j.actorId(),at,j.classification()));changed(db.update("INSERT INTO outbox_event (tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES (?,?,?,1,?,?,?)",j.tenantId(),event,target,action,body,at));}
 private void journalOriginal(FormalEvaluationJobs.Job j,Map<String,Object> row,String action,String target,JsonNode evidence)throws Exception{String body=json.canonical(evidence);same(body,one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action=? AND request_id=? AND trace_id=? AND result='SUCCESS' LIMIT 2",(r,n)->r.getString(1),j.tenantId(),j.projectId(),row.get("audit_id"),j.actorId(),action,target,j.runId())));same(body,one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type=? AND aggregate_revision=1 LIMIT 2",(r,n)->r.getString(1),j.tenantId(),row.get("event_id"),target,action)));}
 private List<Map<String,Object>> executions(String tenant,String run,String step){return db.queryForList("SELECT * FROM formal_evaluation_deterministic_execution WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",tenant,run,step);}private List<Map<String,Object>> outcomes(String tenant,String run,String step){return db.queryForList("SELECT * FROM formal_evaluation_deterministic_outcome WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",tenant,run,step);}
 private static void requireNode(FormalEvaluationExecutionProtocol.Node n){if(!FormalEvaluationExecutionProtocol.deterministic(n))bad();}
 private java.sql.Timestamp now(){return db.queryForObject("SELECT UTC_TIMESTAMP(6)",java.sql.Timestamp.class);}private String hash(JsonNode n)throws Exception{return WireValues.sha256(json.canonical(n).getBytes(StandardCharsets.UTF_8));}private static String id(){return UUID.randomUUID().toString();}private static String text(JsonNode n,String k){if(!n.required(k).isTextual())bad();return n.required(k).textValue();}private static String text(Map<String,Object> row,String k){if(!(row.get(k) instanceof String))bad();return (String)row.get(k);}private static <T>T one(List<T> rows){if(rows.isEmpty())throw new TenantAccessException(ErrorCode.SOURCE_NOT_READY);if(rows.size()!=1)bad();return rows.get(0);}private static void changed(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
